17|/** jsdom-friendly: read clipboard files off any Event without requiring a real ClipboardEvent. */
18|function pastedImageFiles(rawEvent: Event): File[] {
19|  const list =
20|    (rawEvent as Partial<Pick<ClipboardEvent, 'clipboardData'>>).clipboardData
21|      ?.files;
22|  return list
23|    ? Array.from(list).filter(file => file.type.startsWith('image/'))
24|    : [];
25|}
