27|/**
28| * Landing page (UI-Reference §3). T-031 / US-001-01: drop, picker, and Ctrl+V paste
29| * all feed one shared staging list; total line shows "N files · X" per UI §5.1.
30| *
31| * T-032 / US-001-02: the list stays editable until "Send." — afterwards it locks into
32| * upload state (edge case 2) so adds/removes/drops/paste are ignored; Send freezes the
33| * selection-ordered payload (duplicate names preserved, AC #2) for T-034's engine.
34| */
35|function App() {
36|  const [stagedFiles, setStagedFiles] = useState<StagedFile[]>([]);
37|  // Post-"Send." flag drives the lock; refs mirror it for the `[]`-deps handlers
38|  // and hold the ordered payload frozen at send time (duplicates preserved, AC #2).
39|  const [sent, setSent] = useState(false);
40|  const sentRef = useRef(false);
41|  const sendPayloadRef = useRef<SendItem[]>([]);
42|
43|  /** Shared selection entry point; duplicate `File`s are kept once; locked post-"Send." */
44|  const addFiles = (incoming: File[]) => {
45|    if (sent || incoming.length === 0) return;
46|    setStagedFiles(previous => {
47|      const known = new Set<File>(previous.map(entry => entry.file));
48|      const additions = incoming.flatMap(file =>
49|        known.has(file) ? [] : [stageFile(file)],
50|      );
51|      return additions.length > 0 ? [...previous, ...additions] : previous;
52|    });
53|  };
54|
55|  useEffect(() => {
56|    const onWindowPaste = (event: Event) => {
57|      if (sentRef.current) return; // locked list post-"Send." (US-001-02 edge case 2)
58|      const images = pastedImageFiles(event);
59|      if (images.length === 0) return;
60|      setStagedFiles(previous => [
61|        ...previous,
62|        ...stagePastedFiles(images, previous.map(entry => entry.name)),
63|      ]);
64|    };
65|    window.addEventListener('paste', onWindowPaste);
66|    return () => window.removeEventListener('paste', onWindowPaste);
67|  }, []);
68|
69|  const removeFile = (id: string) => {
70|    if (sent) return;
71|    setStagedFiles(previous => removeStagedFiles(previous, id));
72|  };
73|
74|  /** "Send.": capture the selection-ordered payload (duplicates preserved), then lock. */
75|  const handleSend = () => {
76|    if (!canSend(stagedFiles, sent)) return;
77|    sendPayloadRef.current = buildSendPayload(stagedFiles);
78|    sentRef.current = true;
79|    setSent(true);
80|  };
81|
82|  const totalLine = stageSummaryText(stagedFiles);
83|
84|  return (
85|    <div className="landing">
86|      <header className="topbar">
87|        <span className="topbar-brand">ProtoDrop</span>
88|        <div className="topbar-actions">
89|          <button type="button" className="btn btn-ghost">
90|            Sign in
91|          </button>
92|        </div>
93|      </header>
94|      <main className="dropzone">
95|        <DropZone onFilesSelected={addFiles} locked={sent} />
96|
97|        {stagedFiles.length > 0 && (
98|          <section className="staging-panel" aria-label="Selected files">
99|            <ul className="staging-list">
100|              {stagedFiles.map(entry => (
101|                <li key={entry.id} className="file-row">
102|                  <span className="file-name" title={entry.name}>
103|                    {entry.name}
104|                  </span>
105|                  <span className="file-size">
106|                    {formatBytes(entry.size)}
107|                  </span>
108|                  <button
109|                    type="button"
110|                    className="file-remove"
111|                    aria-label={`Remove ${entry.name}`}
112|                    disabled={sent}
113|                    onClick={() => removeFile(entry.id)}
114|                  >
115|                    ✕
116|                  </button>
117|                </li>
118|              ))}
119|            </ul>
120|
121|            <div className="staging-total">{totalLine}</div>
122|
123|            <button
124|              type="button"
125|              className="btn btn-primary send-btn"
126|              onClick={handleSend}
127|              disabled={!canSend(stagedFiles, sent)}
128|            >
129|              Send.
130|            </button>
131|          </section>
132|        )}
133|      </main>
134|    </div>
135|  );
136|}
