1|/**
2| * US-001-01 / US-001-02 (T-031, T-032) — staging model for the landing upload
3| * surface (FR-001-1/2, EC-001-*).
4| *
5| * Mirrors the TA-8.3 `StageEntry` contract so the Zustand upload store can consume
6| * it unchanged later: an entry carries the public data ({id, name, size}) and keeps
7| * the browser `File` attached for UploadEngine to consume in T-034 — no bytes are
8| * written while files sit here (happy path AC #1, "no upload has started yet").
9| *
10| * T-032 adds the stable **Send.** surface: `buildSendPayload` snapshots the list in
11| * selection order without de-duping names; `removeStagedFiles`/`canSend` drive the
12| * pre-send remove/availability rules incl. the post-"Send." lock (edge case 2).
13| */
14|
15|export interface StagedFile {
16|  /** Stable identity (`crypto.randomUUID()`, see TA-8.4) — also the React list key. */
17|  readonly id: string;
18|  /** Exact file name as presented by the OS / picker (rename is handled at copy time, EC-001-1). */
19|  readonly name: string;
20|  /** Size in bytes (1024-based display via {@link formatBytes}). */
21|  readonly size: number;
22|  /** Underlying `File` — consumed later by the upload engine, not sniffed here. */
23|  readonly file: File;
24|}
25|
26|const BASE_NAME = 'pasted-image';
27|
28|function makeId(): string {
29|  const c = globalThis.crypto;
30|  if (c && typeof c.randomUUID === 'function') {
31|    return c.randomUUID();
32|  }
33|  // Non-crypto fallback keeps unit tests deterministic-friendly without a browser.
34|  return `file-${Math.random().toString(36).slice(2, 10)}`;
35|}
36|
37|/** Stage one file dropped, picked or pasted; HEIC / unknown MIME are accepted as-is (EC-001-4). */
38|export function stageFile(file: File): StagedFile {
39|  return { id: makeId(), name: file.name, size: file.size, file };
40|}
41|
42|/**
43| * Derive the next clipboard image file name (`pasted-image.png`, `pasted-image-2.png`, …)
44| * that does not collide with names already in the staging list.
45| */
46|export function nextPastedImageName(taken: Iterable<string>): string {
47|  const used = new Set(taken);
48|  if (!used.has(`${BASE_NAME}.png`)) {
49|    return `${BASE_NAME}.png`;
50|  }
51|  let index = 2;
52|  while (used.has(`${BASE_NAME}-${index}.png`)) {
53|    index += 1;
54|  }
55|  return `${BASE_NAME}-${index}.png`;
56|}
57|
58|/**
59| * Stage clipboard files. Image payloads get derived names; anything else keeps the OS name.
60| */
61|export function stagePastedFiles(
62|  clipboardFiles: ArrayLike<File>,
63|  takenNames: Iterable<string>,
64|): StagedFile[] {
65|  const used = new Set(takenNames);
66|  const staged: StagedFile[] = [];
67|  for (let i = 0; i < clipboardFiles.length; i += 1) {
68|    const file = clipboardFiles[i];
69|    const isImage = file.type.startsWith('image/');
70|    const name = isImage ? nextPastedImageName(used) : file.name;
71|    used.add(name);
72|    staged.push({ id: makeId(), name, size: file.size, file });
73|  }
74|  return staged;
75|}
76|
77|const BYTE_LADDER = ['B', 'KB', 'MB', 'GB', 'TB'] as const;
78|
79|/**
80| * Selection-order snapshot of everything staged (the stable "Send." payload, T-032
81| * US-001-02 AC #2) — names repeat verbatim and entries keep list order; no de-duping.
82| */
83|export function buildSendPayload(stagedFiles: readonly StagedFile[]): SendItem[] {
84|  return stagedFiles.map(entry => ({ name: entry.name, size: entry.size, file: entry.file }));
85|}
86|
87|/**
88| * One entry of the "Send." payload (stable, T-032 AC #2): what UploadEngine will
89| * upload later in T-034. Names arrive verbatim from the staging list — duplicates
90| * stay distinct because each `File` keeps its identity here.
91| */
92|export interface SendItem {
93|  /** Exact staged file name, repeated verbatim for duplicate names. */
94|  readonly name: string;
95|  /** Size in bytes as staged. */
96|  readonly size: number;
97|  /** Underlying `File` consumed by the upload engine in T-034. */
98|  readonly file: File;
99|}
100|
101|/**
102| * Remove one staged entry by id (✕ button). Pure and allocation-cheap; removing the
103| * last entry naturally returns the caller to the empty drop-zone state.
104| */
105|export function removeStagedFiles(
106|  staged: readonly StagedFile[],
107|  id: string,
108|): StagedFile[] {
109|  return staged.filter(entry => entry.id !== id);
110|}
111|
112|/** "Send." availability (UI note on US-001-02): usable iff the list is non-empty and nothing has been sent yet. */
113|export function canSend(staged: readonly StagedFile[], alreadySent: boolean): boolean {
114|  return staged.length > 0 && !alreadySent;
115|}
116|
117|/** Human-friendly bytes, base 1024 with one decimal for units above bytes
118| * (TA-8.5; total line copy is defined by UI §5.1, e.g. "3 files · 2.1 GB").
119| */
120|export function formatBytes(sizeInBytes: number): string {
121|  let value = sizeInBytes;
122|  let unitIndex = 0;
123|  while (value >= 1024 && unitIndex < BYTE_LADDER.length - 1) {
124|    value /= 1024;
125|    unitIndex += 1;
126|  }
127|  if (unitIndex === 0) {
128|    return `${Math.trunc(value)} B`;
129|  }
130|  return `${value.toFixed(1)} ${BYTE_LADDER[unitIndex]}`;
131|}
132|
133|/**
134| * Total staged line, UI-Reference §5.1: "N files · X GB" — count label + combined size.
135| */
136|export function stageSummaryText(staged: ReadonlyArray<Readonly<{ size: number }>>): string {
137|  const count = staged.length;
138|  const totalBytes = staged.reduce((sum, entry) => sum + entry.size, 0);
139|  const unitWord = count === 1 ? 'file' : 'files';
140|  return `${count} ${unitWord} · ${formatBytes(totalBytes)}`;
141|}
